import { PHONE, PHONE_TEL, SITE_URL } from "../lib/data";
import Segments from "./Segments";

// Full-content page renderer: every visible word comes from the page's own
// Google Doc tab (lib/pages-full.js, generated by qa/parse-tabs.py).
// NOTHING here is invented:
// - hero eyebrow / H1 / intro / buttons = the tab's Eyebrow / H1 / intro /
//   CTA Button 1 + 2 lines. Button 1 carries ONLY the phone number.
// - sections = the tab's H2 sections in order; FAQ sections render as
//   <details> items (same pattern as the homepage FAQ).
// - the closing H2 section renders as the final-CTA band. Pages whose last
//   H2 is NOT a closing section (Contact, FAQ-last blogs) get a CTA-only
//   band from the tab's closing "CTA Button:" line.
// - heroImage null = new route with NO photo in this rebuild (per brief):
//   the hero renders on the navy background with no .hero-media div.
// - the old builder-added "Need help now?" note box is GONE (not doc text).

function plainText(parts) {
  return parts
    .map((p) => (typeof p === "string" ? p : p.link))
    .join("");
}

function faqPairs(section) {
  const pairs = [];
  let current = null;
  for (const b of section.blocks) {
    if (b.type === "h3") {
      current = { q: b.text, answers: [] };
      pairs.push(current);
    } else if (b.type === "p" && current) {
      current.answers.push(b.parts);
    }
  }
  return pairs;
}

function SectionBlocks({ blocks }) {
  return (
    <>
      {blocks.map((b, i) => {
        if (b.type === "p") {
          return (
            <p key={i}>
              <Segments parts={b.parts} />
            </p>
          );
        }
        if (b.type === "h3") {
          return <h3 key={i}>{b.text}</h3>;
        }
        if (b.type === "ul") {
          return (
            <ul className="check-list" key={i}>
              {b.items.map((it, j) => (
                <li key={j}>
                  {it.label ? (
                    <>
                      <strong>{it.label}:</strong>{" "}
                      <Segments parts={it.parts} />
                    </>
                  ) : (
                    <Segments parts={it.parts} />
                  )}
                </li>
              ))}
            </ul>
          );
        }
        if (b.type === "meta") {
          return (
            <p key={i}>
              <strong>{b.label}:</strong>{" "}
              {b.label === "Phone" ? (
                <a href={PHONE_TEL}>{b.text}</a>
              ) : (
                b.text
              )}
            </p>
          );
        }
        return null;
      })}
    </>
  );
}

export default function LinkedPage({ page, urlPath }) {
  const serviceSchema =
    page.kind === "service"
      ? {
          "@context": "https://schema.org",
          "@type": "Service",
          "@id": SITE_URL + urlPath + "#service",
          name: page.h1,
          description: page.metaDescription,
          provider: { "@id": SITE_URL + "/#localbusiness" },
          areaServed: { "@type": "City", name: "Elyria" },
          url: SITE_URL + urlPath,
        }
      : null;

  const breadcrumbSchema = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    "@id": SITE_URL + urlPath + "#breadcrumb",
    itemListElement: [
      { "@type": "ListItem", position: 1, name: "Home", item: SITE_URL + "/" },
      { "@type": "ListItem", position: 2, name: page.h1, item: SITE_URL + urlPath },
    ],
  };

  const webPageSchema = {
    "@context": "https://schema.org",
    "@type": "WebPage",
    "@id": SITE_URL + urlPath,
    url: SITE_URL + urlPath,
    name: page.h1,
    isPartOf: { "@id": SITE_URL + "/#website" },
    about: { "@id": SITE_URL + "/#localbusiness" },
    breadcrumb: { "@id": SITE_URL + urlPath + "#breadcrumb" },
  };

  // FAQPage from every FAQ section on the page (Q/A verbatim from the tab).
  const faqSections = page.sections.filter((s) => s.faq);
  const faqPairsAll = faqSections.flatMap((s) => faqPairs(s));
  const faqSchema =
    faqPairsAll.length > 0
      ? {
          "@context": "https://schema.org",
          "@type": "FAQPage",
          "@id": SITE_URL + urlPath + "#faq",
          mainEntity: faqPairsAll.map((f) => ({
            "@type": "Question",
            name: f.q,
            acceptedAnswer: {
              "@type": "Answer",
              text: f.answers.map((a) => plainText(a)).join(" "),
            },
          })),
        }
      : null;

  // HowTo for a tab with a numbered process ("The 10 Steps" — first-steps blog).
  const stepsSection = page.sections.find((s) => s.h2 === "The 10 Steps");
  const howToSchema = stepsSection
    ? {
        "@context": "https://schema.org",
        "@type": "HowTo",
        "@id": SITE_URL + urlPath + "#howto",
        name: stepsSection.h2,
        step: faqPairs(stepsSection).map((st, i) => ({
          "@type": "HowToStep",
          position: i + 1,
          name: st.q,
          text: st.answers.map((a) => plainText(a)).join(" "),
        })),
      }
    : null;

  const closingSection = page.sections.find((s) => s.closing);
  const bodySections = page.sections.filter((s) => !s.closing);

  return (
    <>
      {serviceSchema ? (
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(serviceSchema) }}
        />
      ) : null}
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbSchema) }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(webPageSchema) }}
      />
      {faqSchema ? (
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(faqSchema) }}
        />
      ) : null}
      {howToSchema ? (
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(howToSchema) }}
        />
      ) : null}

      <section className="hero hero-inner-page">
        {page.heroImage ? (
          <div className="hero-media">
            <img src={page.heroImage} alt={page.heroAlt} width="1600" height="900" fetchPriority="high" />
          </div>
        ) : null}
        <div className="hero-inner">
          <p className="eyebrow">{page.eyebrow}</p>
          <h1>{page.h1}</h1>
          {page.intro.map((p, i) => (
            <p className="hero-intro" key={i}>{p}</p>
          ))}
          <div className="hero-cta">
            <a className="btn btn-call" href={PHONE_TEL}>{PHONE}</a>
            <a className="btn btn-help" href={PHONE_TEL}>{page.cta2}</a>
          </div>
        </div>
      </section>

      <div className="wrap">
        <p className="breadcrumb">
          <a href="/">Home</a> / {page.h1}
        </p>
      </div>

      {bodySections.map((section, si) =>
        section.faq ? (
          <section className="section section-alt" id="faq" key={si}>
            <div className="wrap">
              <div className="section-head">
                <h2>{section.h2}</h2>
              </div>
              <div className="faq-list">
                {faqPairs(section).map((f) => (
                  <details className="faq-item" key={f.q}>
                    <summary>
                      <h3>{f.q}</h3>
                    </summary>
                    <div className="faq-answer">
                      {f.answers.map((a, ai) => (
                        <p key={ai}>
                          <Segments parts={a} />
                        </p>
                      ))}
                    </div>
                  </details>
                ))}
              </div>
            </div>
          </section>
        ) : (
          <section
            className={si % 2 === 1 ? "section section-alt" : "section"}
            key={si}
          >
            <div className="wrap prose">
              <h2>{section.h2}</h2>
              <SectionBlocks blocks={section.blocks} />
            </div>
          </section>
        )
      )}

      {closingSection ? (
        <section className="section final-cta">
          <div className="wrap">
            <h2>{closingSection.h2}</h2>
            <SectionBlocks blocks={closingSection.blocks} />
            <div className="hero-cta">
              <a className="btn btn-call" href={PHONE_TEL}>{PHONE}</a>
            </div>
          </div>
        </section>
      ) : (
        <section className="section final-cta">
          <div className="wrap">
            <div className="hero-cta">
              <a className="btn btn-call" href={PHONE_TEL}>{PHONE}</a>
            </div>
          </div>
        </section>
      )}
    </>
  );
}
